short s1 = 100;
char c1 = 'A';
auto sum_sc = s1 + c1;
// s1 and c1 promoted to int for calculation.
// decltype(sum_sc) is int.

short s2 = 30000;
short s3 = 30000;
auto prod_s = s2 * s3;
// Result (900,000) stored safely in int
// Integral promotion prevents overflow if calculation stayed short.

float f = 10.5f;
long l = 100L;
auto mixed_sum = f + l;
// Usual Conversion: l (long) converted to f (float).
// decltype(mixed_sum) is float.

double d = 5.0;
auto final_sum = mixed_sum + d;
// float converted to double (highest rank wins).
// decltype(final_sum) is double.

int x = 10;
double y = 20.0;
// Conditional Operator requires common type:
auto res1 = true ? x : y;
// (int and double) -> double. decltype(res1) is double.

unsigned int ui = 5U;
int si = -10;
// Signed converts to unsigned (potential large positive result).
if (si < ui) { /* Actually FALSE */ }
